21	/**
22	 * @brief Construct a TileOperator from a TIR Call using a registered builder.
23	 *
24	 * Looks up a builder function in the "TLOpBuilder" Op attribute map for the
25	 * operator referenced by `call` and invokes it to produce a TileOperator. If no
26	 * builder is registered for the operator, returns a default-constructed (empty)
27	 * TileOperator.
28	 *
29	 * @param call The TIR Call whose operator and arguments will be used to build
30	 * the TileOperator.
31	 * @return TileOperator The constructed TileOperator, or a default (empty)
32	 * TileOperator if no builder exists.
33	 */
34	TileOperator ParseOperator(Call call) {
35	  auto op_map = Op::GetAttrMap<OpBuilderFunc>("TLOpBuilder");
36	  Op op = call->op.as<Op>().value();
37	  if (op_map.count(op)) {
38	    auto tile_op = op_map[op](call->args, call->annotations);
39	    ICHECK(tile_op.defined());
40	    return tile_op;
41	  }
42	  return TileOperator();
43	}
44	
45	/**
46	 * @brief Parse a TileOperator from a TIR statement if it contains a call.
47	 *
48	 * If `stmt` is an Evaluate node whose value is a Call, delegates to
49	 * ParseOperator(Call, BufferMap) and returns the resulting TileOperator.
50	 * Otherwise returns a default-constructed (empty) TileOperator.
51	 *
52	 * @param stmt TIR statement to inspect; expected to be an Evaluate of a Call.
53	 * @return TileOperator Parsed operator on success, or a default (empty)
54	 * TileOperator if `stmt` is not an Evaluate(Call).
55	 */
56	TileOperator ParseOperator(Stmt stmt) {
57	  if (stmt.as<Evaluate>() && stmt.as<EvaluateNode>()->value.as<CallNode>()) {
58	    auto call = stmt.as<EvaluateNode>()->value.as<CallNode>();
59	    return ParseOperator(tvm::ffi::GetRef<Call>(call));
60	  }
61	  return TileOperator();
62	}
63	
64	/**
65	 * @brief Extracts the Var referenced by a `tvm_access_ptr` call expression.
66	 *
67	 * The function expects `expr` to be a `Call` to the builtin `tvm_access_ptr`
68	 * and returns the `Var` found in the call's second argument (`args[1]`). The
69	 * function performs runtime checks and will abort if `expr` is not a call, the
70	 * call is not `tvm_access_ptr`, or the second argument is not a `Var`.
71	 *
72	 * @param expr A `PrimExpr` representing a `tvm_access_ptr(...)` call.
73	 * @return tvm::Var The `Var` referenced by the `tvm_access_ptr` call.
74	 */
75	Var GetVarFromAccessPtr(const PrimExpr &expr) {
76	  auto call = expr.as<CallNode>();
77	  ICHECK(call);
78	  if (call->op.same_as(builtin::tvm_access_ptr())) {
79	    auto var = call->args[1].as<VarNode>();
80	    ICHECK(var);
81	    return tvm::ffi::GetRef<Var>(var);
82	  }
83	  if (call->op.same_as(tl::access_ptr())) {
84	    ICHECK_EQ(call->args.size(), 3U);
85	    auto load = call->args[0].as<BufferLoadNode>();
86	    ICHECK(load);
87	    auto var = load->buffer->data.as<VarNode>();
88	    ICHECK(var);
89	    return tvm::ffi::GetRef<Var>(var);
90	  }
91	  LOG(FATAL) << "GetVarFromAccessPtr expects a tvm_access_ptr or tl.access_ptr "
92	                "call, but got: "
93	             << tvm::ffi::GetRef<Call>(call);
94	}
95	
96	} // namespace tl
97	} // namespace tvm
