1	/*!
2	 * \file tl/op/copy.cc
3	 * \brief Define the copy operator, backend dispatch, and shared normal-copy
4	 *        lowering helpers.
5	 */
6	
7	#include "copy.h"
8	#include "../transform/common/loop_fusion_utils.h"
9	#include "../transform/loop_partition.h"
10	#include "../transform/loop_vectorize.h"
11	#include "support/check.h"
12	#include "utils.h"
13	#include <tvm/ir/cast.h>
14	#include <tvm/runtime/logging.h>
15	
16	#include "builtin.h"
17	#include <tvm/tirx/analysis.h>
18	#include <tvm/tirx/op.h>
19	#include <tvm/tirx/op_attr_types.h>
20	
21	#include <limits>
22	#include <sstream>
23	#include <vector>
24	
25	namespace tvm {
26	namespace tl {
27	
28	using namespace tirx;
29	using namespace ffi;
30	
31	Stmt LowerNormalCopy(const CopyNode &op, const LowerArgs &lower_args,
32	                     arith::Analyzer *analyzer) {
33	  bool is_cpu_target = lower_args.target->GetTargetDeviceType() == kDLCPU;
34	  auto simt_loop = op.MakeSIMTLoop(analyzer);
35	  auto fused_loop = Downcast<For>(ParallelLoopFuser::Fuse(simt_loop));
36	
37	  For vectorized_thread_loop;
38	  auto par_op = ParallelOp(fused_loop);
39	
40	  if (is_cpu_target || IsLocalBuffer(op.src) || IsLocalBuffer(op.dst)) {
41	    if (IsLocalBuffer(op.src) && !IsLocalBuffer(op.dst)) {
42	      // A conflict write only occurs when multiple threads write to the same
43	      // global address. If any dst_range dimension's min depends on the thread
44	      // variable, each thread targets a distinct location and there is no
45	      // conflict.
46	      bool dst_depends_on_thread = false;
47	      for (const auto &range : op.dst_range) {
48	        if (tirx::UsesVar(range->min, [&](const VarNode *v) {
49	              return v == lower_args.thread_var.get();
50	            })) {
51	          dst_depends_on_thread = true;
52	          break;
53	        }
54	      }
55	      if (!dst_depends_on_thread) {
56	        DLOG(WARNING) << "Copy from local buffer `" << op.src->name << "` to "
57	                      << op.dst.scope() << " buffer `" << op.dst->name
58	                      << "` may cause conflicted write.";
59	      }
60	    }
61	    vectorized_thread_loop = VectorizeLoop(fused_loop, lower_args.layout_map);
62	    return vectorized_thread_loop;
63	  }
64	
65	  std::vector<InferLevel> levels = {InferLevel::kCommon, InferLevel::kStrict,
66	                                    InferLevel::kFree};
67	  for (auto level : levels) {
68	    par_op->InferLayout({lower_args.target,
69	                         lower_args.thread_bounds,
70	                         lower_args.layout_map,
71	                         analyzer,
72	                         false,
73	                         lower_args.buffer_remap,
74	                         {}},
75	                        level);
76	  }
77	  auto loop_layout = par_op->GetLoopLayout();
78	  return LowerParallelLoop(
79	      par_op->GetRoot(), loop_layout, lower_args.thread_var, analyzer,
80	      lower_args.layout_map, par_op->GetPredicate(lower_args.thread_var),
81	      /*parallel_loop=*/true, /*should_vectorize=*/true,
82	      par_op->LoopLayoutRequiresPaddingGuard());
83	}
84	
85	namespace {
86	
87	std::vector<CopyImpl> &CopyImplRegistry() {
88	  static std::vector<CopyImpl> registry;
89	  return registry;
90	}
91	
92	const CopyImpl &ResolveCopyImpl(Target target) {
93	  const auto &registry = CopyImplRegistry();
94	  const CopyImpl *best_impl = nullptr;
95	  int best_priority = std::numeric_limits<int>::min();
96	  for (const CopyImpl &impl : registry) {
97	    if (impl.match_target(target) && impl.priority >= best_priority) {
98	      best_impl = &impl;
99	      best_priority = impl.priority;
100	    }
101	  }
102	  ICHECK(best_impl != nullptr)
103	      << "tl.copy requires a target-specific implementation, but no copy "
104	         "implementation is registered for "
105	      << target->str();
106	  return *best_impl;
107	}
108	
109	LayoutMap InferCopyLayout(const CopyNode &op,
110	                          const LayoutInferArgs &layout_args,
111	                          InferLevel level) {
112	  return ResolveCopyImpl(layout_args.target)
113	      .infer_layout(op, layout_args, level);
114	}
115	
116	Stmt LowerCopyForTarget(const CopyNode &op, const LowerArgs &lower_args,
117	                        arith::Analyzer *analyzer) {
118	  return ResolveCopyImpl(lower_args.target).lower(op, lower_args, analyzer);
119	}
