266	
267	// Constructs a Copy operator node from call arguments and annotations.
268	// args[0]: source region, args[1]: destination region
269	// annotations: Map containing common SIMT hints and backend-specific metadata.
270	Copy::Copy(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
271	  ObjectPtr<CopyNode> node = make_object<CopyNode>();
272	  auto src_access = NormalizeToAccessRegion(args[0], kAccessRead);
273	  auto dst_access = NormalizeToAccessRegion(args[1], kAccessWrite);
274	  node->src = src_access.region->buffer;
275	  node->dst = dst_access.region->buffer;
276	  node->src_range = src_access.region->region;
277	  node->dst_range = dst_access.region->region;
278	  node->SetAccessRegions({src_access, dst_access});
279	  // Copy annotations from the Call node
280	  node->annotations = annotations;
281	  if (auto dst_block = node->annotations.Get("dst_block")) {
282	    if (auto int_imm = dst_block->as<IntImmNode>()) {
283	      if (int_imm->value != -1) {
284	        node->dst_block = Integer(int_imm->value);
285	      }
286	    } else {
287	      node->dst_block = Downcast<PrimExpr>(dst_block.value());
288	    }
289	  }
290	  data_ = std::move(node);
291	}
292	
293	// Creates a shallow clone of this CopyNode.
294	TileOperator CopyNode::Clone() const {
295	  auto op = make_object<CopyNode>(*this);
296	  if (par_op_.defined()) {
297	    op->par_op_ = Downcast<ParallelOp>(par_op_->Clone());
298	  }
299	  return Copy(op);
300	}
301	
302	// Creates iterator variables for dimensions with extent > 1.
303	Array<IterVar> CopyNode::MakeIterVars() const {
304	  // Choose the range set from the lowest-level memory scope between src and
305	  // dst. Scope levels: global < shared/shared.dyn/shared.tmem < local.fragment
306	  // (fragment)
307	  auto scope_level = [](const Buffer &b) -> int {
308	    String s = b.scope();
309	    if (s == "local.fragment" || s == "local")
310	      return 2;
311	    if (s == "shared" || s == "shared.dyn" || s == "shared.tmem")
312	      return 1;
313	    // default to global level for unknown scopes
314	    return 0;
315	  };
316	
317	  int src_level = scope_level(src);
318	  int dst_level = scope_level(dst);
319	  bool base_is_src = (src_level >= dst_level);
320	  const Array<Range> &base_ranges = base_is_src ? src_range : dst_range;
321	
322	  // Sanity check: when switching away from the original (src_range),
323	  // ensure the chosen base ranges are not provably smaller than the original
324	  // per dimension. This guards against generating undersized loop domains.
325	  // Improved logic: use two pointers to traverse both base_ranges and
326	  // src_range, skipping dimensions with extent == 1. The number of non-1
327	  // extents must match.
328	  arith::Analyzer analyzer;
329	
330	  size_t base_dim = 0, src_dim = 0;
331	  while (base_dim < base_ranges.size() && src_dim < src_range.size()) {
332	    // Skip base extents that are 1
333	    while (base_dim < base_ranges.size() &&
334	           is_one(base_ranges[base_dim]->extent)) {
335	      ++base_dim;
336	    }
337	    // Skip src extents that are 1
338	    while (src_dim < src_range.size() && is_one(src_range[src_dim]->extent)) {
339	      ++src_dim;
340	    }
341	    // Both indices now at non-1, or at end
342	    if (base_dim < base_ranges.size() && src_dim < src_range.size()) {
343	      PrimExpr base_ext = base_ranges[base_dim]->extent;
344	      PrimExpr src_ext = src_range[src_dim]->extent;
345	      // Only fail if base extent is provably smaller than src extent
346	      if (analyzer.CanProve(base_ext < src_ext)) {
347	        std::ostringstream oss;
348	        oss << "Selected loop range is smaller than original src range at "
349	               "matched non-1 dimension: "
350	            << "base(extent=" << base_ext
351	            << ", scope=" << (base_is_src ? src.scope() : dst.scope())
352	            << ", min=" << base_ranges[base_dim]->min
353	            << ", base_dim=" << base_dim << ") < src(extent=" << src_ext
354	            << ", min=" << src_range[src_dim]->min << ", src_dim=" << src_dim
355	            << ", scope=" << src.scope() << ") for src=" << src->name
356	            << ", dst=" << dst->name << "\n";
357	        oss << "src buffer: " << src->name << ", scope=" << src.scope() << "\n";
358	        oss << "dst buffer: " << dst->name << ", scope=" << dst.scope() << "\n";
359	        oss << "base_ranges[" << base_dim
360	            << "]: min=" << base_ranges[base_dim]->min
361	            << ", extent=" << base_ext << "\n";
362	        oss << "src_ranges[" << src_dim << "]: min=" << src_range[src_dim]->min
363	            << ", extent=" << src_ext << "\n";
364	        LOG(FATAL) << oss.str();
365	      }
366	      ++base_dim;
367	      ++src_dim;
368	    }
369	  }
370	
371	  // Any remaining unmatched dimensions in either range must all have extent ==
372	  // 1
373	  while (base_dim < base_ranges.size()) {
374	    ICHECK(is_one(base_ranges[base_dim]->extent))
375	        << "base_ranges has extra non-1 extent at dim " << base_dim;
376	    ++base_dim;
377	  }
378	  while (src_dim < src_range.size()) {
379	    ICHECK(is_one(src_range[src_dim]->extent))
380	        << "src_range has extra non-1 extent at dim " << src_dim;
381	    ++src_dim;
382	  }
383	
384	  Array<IterVar> loop_vars;
385	  size_t idx = 0;
386	  for (size_t i = 0; i < base_ranges.size(); i++) {
387	    if (is_one(base_ranges[i]->extent))
388	      continue;
389	    Var var = Var(std::string{char('i' + idx)}, base_ranges[i]->extent->dtype);
390	    idx++;
391	    loop_vars.push_back(
392	        {Range(0, base_ranges[i]->extent), var, IterVarType::kDataPar});
393	  }
394	  return loop_vars;
395	}
396	
397	// Generates index expressions for accessing src (src_dst=0) or dst (src_dst=1)
398	// buffers.
399	Array<PrimExpr> CopyNode::MakeIndices(const Array<IterVar> &ivs,
400	                                      int src_dst) const {
401	  Array<PrimExpr> indices;
402	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
403	  size_t idx = 0;
404	  for (size_t i = 0; i < ranges.size(); i++) {
405	    if (is_one(ranges[i]->extent))
406	      indices.push_back(ranges[i]->min);
407	    else {
408	      indices.push_back(ranges[i]->min + ivs[idx]->var);
409	      idx++;
410	    }
411	  }
412	  ICHECK(idx == ivs.size())
413	      << "idx = " << idx << ", ivs.size() = " << ivs.size()
414	      << "src name = " << src->name << ", dst name = " << dst->name;
415	  return indices;
416	}
417	
418	// Builds a boundary predicate for memory accesses.
419	// Returns a conjunction of bounds checks, or empty PrimExpr if all checks pass.
420	PrimExpr CopyNode::MakePredicate(arith::Analyzer *analyzer,
421	                                 const Array<IterVar> &ivs,
422	                                 Array<PrimExpr> extents, int src_dst) const {
423	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
424	
425	  Array<PrimExpr> cond_list;
426	  ICHECK(extents.size() == ranges.size()) << extents << " " << ranges;
427	  size_t idx = 0;
428	  for (size_t i = 0; i < ranges.size(); i++) {
429	    if (is_one(ranges[i]->extent))
430	      continue;
431	    PrimExpr cond = ranges[i]->min + ivs[idx]->var < extents[i];
432	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
433	      cond_list.push_back(cond);
434	    }
435	    cond = ranges[i]->min + ivs[idx]->var >= 0;
436	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
437	      cond_list.push_back(cond);
438	    }
439	    idx++;
440	  }
441	  if (cond_list.empty())
442	    return {};
443	  else {
444	    PrimExpr cond = cond_list[0];
445	    for (size_t i = 1; i < cond_list.size(); i++)
446	      cond = And(cond, cond_list[i]);
447	    return cond;
448	  }
449	}
450	
451	// Constructs a SIMT-style nested loop that implements the copy.
452	For CopyNode::MakeSIMTLoop(arith::Analyzer *analyzer) const {
453	  if (IsFP4UnpackLoad(src, dst)) {
454	    LOG(FATAL) << "SIMT copy from packed global float4_e2m1fn to unpacked "
455	               << "shared float4_e2m1_unpacked is not supported; use "
456	               << "T.tma_copy() for FP4 unpack loads (src=" << src->name
457	               << ", dst=" << dst->name << ").";
458	  }
459	
460	  Array<IterVar> loop_vars = MakeIterVars();
461	  bool is_scalar = loop_vars.empty();
462	
463	  for (const auto &iv : loop_vars)
464	    analyzer->Bind(iv->var, iv->dom);
465	  ICHECK(loop_vars.size() <= src_range.size())
466	      << "loop_vars.size() = " << loop_vars.size()
467	      << ", src_range.size() = " << src_range.size() << ", src = " << src->name
468	      << ", dst = " << dst->name;
469	
470	  ICHECK(loop_vars.size() <= dst_range.size())
471	      << "loop_vars.size() = " << loop_vars.size()
472	      << ", dst_range.size() = " << dst_range.size() << ", src = " << src->name
473	      << ", dst = " << dst->name;
474	
475	  Array<PrimExpr> src_indices = MakeIndices(loop_vars, 0);
476	  Array<PrimExpr> dst_indices = MakeIndices(loop_vars, 1);
477	
478	  PrimExpr src_predicate = MakePredicate(analyzer, loop_vars, src->shape, 0);
479	  PrimExpr dst_predicate = MakePredicate(analyzer, loop_vars, dst->shape, 1);
480	
481	  PrimExpr value = BufferLoad(src, src_indices);
482	  if (src->dtype != dst->dtype)
483	    value = Cast(dst->dtype, value);
484	  if (src_predicate.defined())
485	    value = if_then_else(src_predicate, value, make_zero(dst->dtype));
486	
487	  Stmt body = BufferStore(dst, value, dst_indices);
488	  if (dst_predicate.defined())
489	    body = IfThenElse(dst_predicate, body);
490	  if (is_scalar) {
491	    return For(Var("i"), 0, 1, ForKind::kSerial, body);
492	  }
493	
494	  for (int i = loop_vars.size() - 1; i >= 0; i--) {
495	    Map<String, ObjectRef> loop_annotations;
496	
497	    // Only attach the parallel related annotations on the outermost loop (i ==
498	    // 0)
499	    if (i == 0) {
500	      if (annotations.count(attr::kCoalescedWidth)) {
501	        loop_annotations.Set(attr::kCoalescedWidth,
502	                             annotations.Get(attr::kCoalescedWidth).value());
503	      }
504	      if (annotations.count(attr::kParallelLoopLayout)) {
505	        loop_annotations.Set(
506	            attr::kParallelLoopLayout,
507	            annotations.Get(attr::kParallelLoopLayout).value());
508	      }
509	    }
510	
511	    body = For(loop_vars[i]->var, 0, loop_vars[i]->dom->extent,
512	               ForKind::kParallel, body, std::nullopt, loop_annotations);
513	  }
514	  return Downcast<For>(body);
515	}
516	
517	LayoutMap CopyNode::InferLayout(const LayoutInferArgs &layout_args,
518	                                InferLevel level) const {
519	  return InferCopyLayout(*this, layout_args, level);
520	}
521	
522	LayoutMap CopyNode::InferSIMTLayout(const LayoutInferArgs &layout_args,
523	                                    InferLevel level) const {
524	  if (!par_op_.defined()) {
525	    arith::Analyzer analyzer;
526	    par_op_ = ParallelOp(MakeSIMTLoop(&analyzer));
527	  }
528	  return par_op_->InferLayout(layout_args, level);
529	}
530	// Lowers the copy operation by dispatching to the selected target
531	// implementation.
532	Stmt CopyNode::Lower(const LowerArgs &lower_args,
533	                     arith::Analyzer *analyzer) const {
534	  return LowerCopyForTarget(*this, lower_args, analyzer);
535	}
536	
537	// Constructs an Im2ColOp node from call arguments.
538	// args: src, dst, nhw_step, c_step, kernel, stride, dilation, padding,
539	// eviction_policy
540	Im2ColOp::Im2ColOp(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
541	  ObjectPtr<Im2ColOpNode> node = make_object<Im2ColOpNode>();
542	  auto src_access = NormalizeToAccessRegion(args[0], kAccessRead);
543	  auto dst_access = NormalizeToAccessRegion(args[1], kAccessWrite);
544	  node->srcRegion_ = src_access.region;
545	  node->dstRegion_ = dst_access.region;
546	  node->SetAccessRegions({src_access, dst_access});
547	  node->src_ = node->srcRegion_->buffer;
548	  node->dst_ = node->dstRegion_->buffer;
549	  node->nhw_step_ = args[2];
550	  node->c_step_ = args[3];
551	  node->kernel_ = args[4].as<IntImm>().value()->value;
552	  node->stride_ = args[5].as<IntImm>().value()->value;
553	  node->dilation_ = args[6].as<IntImm>().value()->value;
554	  node->padding_ = args[7].as<IntImm>().value()->value;
555	  node->eviction_policy_ = args[8].as<IntImm>().value()->value;
556	  node->annotations_ = annotations;
557	  data_ = std::move(node);
558	}
559	
560	// Creates a shallow copy of this Im2ColOpNode.
561	TileOperator Im2ColOpNode::Clone() const {
562	  auto op = make_object<Im2ColOpNode>(*this);
563	  return Im2ColOp(op);
564	}
565	
566	Stmt Im2ColOpNode::Lower(const LowerArgs &lower_args,
567	                         arith::Analyzer *analyzer) const {
568	  return LowerIm2ColForTarget(*this, lower_args, analyzer);
569	}
570	
571	// Register the Copy operation with TVM's TIR system
572	// This makes the copy operation available for use in TVM programs
573	// - Takes 5 inputs: src_buffer, dst_buffer, and annotation-driven options.
574	// - Marked as opaque since it has side effects (memory writes)
575	TIR_REGISTER_TL_TILE_OP(Copy, copy)
576	    .set_num_inputs(5)
577	    .set_attr<TCallEffectKind>("TCallEffectKind",
578	                               Integer(CallEffectKind::kOpaque));
579	
580	TVM_REGISTER_OP("tl.tileop.async_copy")
581	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "async_copy")
582	    .set_attr<OpBuilderFunc>("TLOpBuilder",
583	                             [](Array<PrimExpr> args,
584	                                Map<String, ObjectRef> annotations) {
585	                               Map<String, ObjectRef> ann = annotations;
586	                               ann.Set("is_async_copy",
587	                                       IntImm(DataType::Int(32), 1));
588	                               return Copy(args, ann);
589	                             })
590	    .set_num_inputs(5)
591	    .set_attr<TCallEffectKind>("TCallEffectKind",
592	                               Integer(CallEffectKind::kOpaque));
593	
594	// Register the tma_copy operation — same as copy but forces TMA path
595	// and emits only expect_tx + tma_load (no wait).
596	TVM_REGISTER_OP("tl.tileop.tma_copy")
597	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "tma_copy")
598	    .set_attr<OpBuilderFunc>("TLOpBuilder",
599	                             [](Array<PrimExpr> args,
600	                                Map<String, ObjectRef> annotations) {
601	                               Map<String, ObjectRef> ann = annotations;
602	                               ann.Set("is_tma_copy",
603	                                       IntImm(DataType::Int(32), 1));
604	                               return Copy(args, ann);
605	                             })
606	    .set_num_inputs(5)
607	    .set_attr<TCallEffectKind>("TCallEffectKind",
608	                               Integer(CallEffectKind::kOpaque));
609	
610	// Register the maca_async_copy operation - for MACA async copy using
611	// memcpy_async and barrier_arrive_and_wait.
612	TVM_REGISTER_OP("tl.tileop.maca_async_copy")
613	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "maca_async_copy")
614	    .set_attr<OpBuilderFunc>("TLOpBuilder",
615	                             [](Array<PrimExpr> args,
616	                                Map<String, ObjectRef> annotations) {
617	                               Map<String, ObjectRef> ann = annotations;
618	                               ann.Set("is_async_copy",
619	                                       IntImm(DataType::Int(32), 1));
620	                               return Copy(args, ann);
621	                             })
622	    .set_num_inputs(5)
623	    .set_attr<TCallEffectKind>("TCallEffectKind",
624	                               Integer(CallEffectKind::kOpaque));
625	
626	// Layout inference hook - returns empty map (no layout suggestions).
627	LayoutMap Im2ColOpNode::InferLayout(const LayoutInferArgs &layout_args,
628	                                    InferLevel level) const {
629	  return {};
630	}
631	
632	// Register the Im2Col operation with TVM's TIR system
633	// This operation performs im2col transformation for 2D convolutions using a
634	// target-specific lowering.
635	// - Takes 9 inputs: src_buffer, dst_buffer, nhw_step, c_step, kernel, stride,
636	// dilation, padding, eviction_policy
637	// - Marked as opaque since it has side effects (memory writes)
638	TIR_REGISTER_TL_TILE_OP(Im2ColOp, im2col)
639	    .set_num_inputs(9)
640	    .set_attr<TCallEffectKind>("TCallEffectKind",
641	                               Integer(CallEffectKind::kOpaque));
642	
643	// Deprecated compatibility alias. Prefer tl.tileop.im2col; this alias is
644	// scheduled for removal in TileLang 0.14.0.
645	TVM_REGISTER_OP("tl.tileop.c2d_im2col")
646	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "c2d_im2col")
647	    .set_attr<OpBuilderFunc>("TLOpBuilder",
648	                             [](Array<PrimExpr> args,
649	                                Map<String, ObjectRef> annotations) {
650	                               return Im2ColOp(args, annotations);
651	                             })
652	    .set_num_inputs(9)
653	    .set_attr<TCallEffectKind>("TCallEffectKind",
654	                               Integer(CallEffectKind::kOpaque));
655	
656	TVM_FFI_STATIC_INIT_BLOCK() {
657	  CopyNode::RegisterReflection();
