/*!
 * \file tl/op/op.h
 * \brief Tile library operations.
 *
 */

#ifndef TVM_TL_OP_OP_H_
#define TVM_TL_OP_OP_H_

#include <array>
#include <cstdint>
#include <functional>
#include <optional>
#include <string>
#include <utility>
#include <vector>

#include <tvm/arith/analyzer.h>
#include <tvm/ir/op.h>
#include <tvm/target/target.h>
#include <tvm/tirx/buffer.h>
#include <tvm/tirx/op.h>
#include <tvm/tirx/op_attr_types.h>
#include <tvm/tirx/stmt.h>

#include "../layout/layout.h"
#include "support/check.h"

namespace tvm {
namespace tl {

using AddWorkspaceCallback = std::function<PrimExpr(int, DataType)>;
// Allocate a compiler-generated shared mbarrier slot. The optional hint names
// the backing barrier buffer when the first slot is created; later slots share
// the same buffer and may ignore the hint.
using AllocMBarrierCallback =
    std::function<int(int arrive_count, std::optional<std::string> name)>;
using UpdateBarrierArriveCallback = std::function<void(tirx::Var, PrimExpr)>;
// Record a minimum shared-memory base alignment (bytes) required for the
// buffer backed by the given data Var (e.g. TMA/MMA swizzle constraints).
using RequireSmemAlignmentCallback = std::function<void(tirx::Var, int)>;
using LayoutMap = ffi::Map<tirx::Buffer, Layout>;
using BufferMap = ffi::Map<tirx::Var, tirx::Buffer>;

enum AccessMask : int {
  kAccessRead = 1,
  kAccessWrite = 2,
  kAccessReadWrite = kAccessRead | kAccessWrite,
};

struct AccessRegion {
  tirx::BufferRegion region;
  int access_mask{kAccessReadWrite};
};

struct AccessRegions {
  ffi::Array<tirx::BufferRegion> reads;
  ffi::Array<tirx::BufferRegion> writes;
};

inline void AppendAccessRegionByMask(const AccessRegion &access,
                                     ffi::Array<tirx::BufferRegion> *reads,
                                     ffi::Array<tirx::BufferRegion> *writes) {
  if (!access.region.defined()) {
    return;
  }
  if (access.access_mask & kAccessRead) {
    reads->push_back(access.region);
  }
  if (access.access_mask & kAccessWrite) {
    writes->push_back(access.region);
  }
}

enum class InferLevel : uint8_t {
  kFree = 0,
  kCommon = 1,
  kStrict = 2,
};

/// Convert InferLevel enum to string for debugging
inline const char *InferLevelToString(InferLevel level) {
  switch (level) {
  case InferLevel::kFree:
    return "Free";
  case InferLevel::kCommon:
    return "Common";
  case InferLevel::kStrict:
    return "Strict";
  default:
    return "Unknown";
  }
}

struct LowerArgs {
  Target target;
  Range thread_bounds;
  tirx::Var thread_var;
  LayoutMap layout_map;
  ffi::Map<tirx::Buffer, tirx::Buffer> buffer_remap;
  // Map from Bind variable to its bound expression, for resolving
  // fragment buffer accesses through Bind values
  ffi::Map<tirx::Var, PrimExpr> bind_var_to_expr;
  // Fallback mbarrier parity for ops that do not carry an explicit
  // tl.pipeline_mbar_phase_expr annotation. LowerTileOp derives this from the
  // nearest enclosing serial loop so non-pipelined TMA loops still alternate
  // barrier phase correctly.
  PrimExpr mbar_phase_expr = IntImm(DataType::Int(32), 0);
  // Pointer to the shared.barrier buffer for compiler-generated mbarriers.
  // Points to the LowerTileOpPass member so copy.cc sees the buffer
  // even when created lazily by the alloc_mbarrier callback.
  ffi::Optional<tirx::Buffer> *mbarrier_buffer = nullptr;
  // Product of cluster_dims (from block annotation). Defaults to 1 (no
  // cluster). Used by TMA copy lowering to scale expect_tx bytes for cluster
  // barriers.
  int cluster_size = 1;

  // Callbacks used by op lowerings to request pass-owned resources or report
  // metadata that later passes need.
  AddWorkspaceCallback add_workspace = nullptr;
  AllocMBarrierCallback alloc_mbarrier = nullptr;
  UpdateBarrierArriveCallback update_barrier_arrive = nullptr;
  // Optional callback to record a minimum shared-memory base alignment for a
  // buffer's data Var. Lowerings that bind a buffer to a swizzle-sensitive
  // instruction (TMA bulk copy, wgmma/tcgen05 descriptors) report the
  // alignment implied by the chosen swizzle mode here; LowerTileOp collects
  // the results into the kSmemAlignmentMap PrimFunc attribute.
  RequireSmemAlignmentCallback require_smem_alignment = nullptr;
};

struct LayoutInferArgs {
  Target target;
  Range thread_bounds;
  LayoutMap layout_map;
  arith::Analyzer *analyzer;
  bool buffer_oob = false;
  ffi::Map<tirx::Buffer, tirx::Buffer> buffer_remap;
  // Map from Bind variable to its bound expression, for resolving
  // fragment buffer accesses through Bind values
  ffi::Map<tirx::Var, PrimExpr> bind_var_to_expr;
  // Whether the current TileOp is nested inside a pipelined loop
  // (i.e. a surrounding loop annotated with num_stages > 0).
  bool in_pipeline = false;
};

class TileOperator;

class TileOperatorNode : public ffi::Object {
public:
  virtual tirx::Stmt Lower(const LowerArgs &lower_args,
                           arith::Analyzer *analyzer) const = 0;

  virtual LayoutMap InferLayout(const LayoutInferArgs &layout_args,
                                InferLevel level) const = 0;

  virtual TileOperator Clone() const = 0;

  virtual AccessRegions GetAccessRegions() const {
    AccessRegions result;
    for (const auto &access : access_regions_) {
      AppendAccessRegionByMask(access, &result.reads, &result.writes);
    }
    return result;
  }

  void SetAccessRegions(std::vector<AccessRegion> access_regions) {
    access_regions_ = std::move(access_regions);
  }

  TVM_FFI_DECLARE_OBJECT_INFO("tl.TileOperator", TileOperatorNode, ffi::Object);

protected:
  std::vector<AccessRegion> access_regions_;
};

class TileOperator : public ffi::ObjectRef {
public:
  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(TileOperator, ffi::ObjectRef,
                                             TileOperatorNode);
};

tirx::Var GetVarFromAccessPtr(const PrimExpr &expr);

TileOperator ParseOperator(tirx::Call call);
TileOperator ParseOperator(tirx::Stmt stmt);

using OpBuilderFunc = ffi::TypedFunction<TileOperator(
    ffi::Array<PrimExpr>, ffi::Map<ffi::String, ffi::ObjectRef>)>;

#define TIR_REGISTER_TL_TILE_OP(Entry, OpName)                                 \
  const Op &Entry::Get() {                                                     \
    static const Op &op = Op::Get("tl.tileop." #OpName);                       \
    return op;                                                                 \
  }                                                                            \
  TVM_REGISTER_OP("tl.tileop." #OpName)                                        \
      .set_attr<tirx::TScriptPrinterName>("TScriptPrinterName", #OpName)       \
      .set_attr<OpBuilderFunc>(                                                \
          "TLOpBuilder",                                                       \
          [](ffi::Array<PrimExpr> args,                                        \
             ffi::Map<ffi::String, ffi::ObjectRef> annotations) {              \
            return Entry(args, annotations);                                   \
          })

} // namespace tl
} // namespace tvm

#endif // TVM_TL_OP_OP_H_

/*!
 * \file tl/op/copy.h
 * \brief Copy operations
 */

#ifndef TVM_TL_OP_COPY_H_
#define TVM_TL_OP_COPY_H_

#include "builtin.h"
#include "operator.h"
#include "parallel.h"
#include "support/check.h"

#include <utility>

namespace tvm {
namespace tl {
using namespace tirx;
using namespace ffi;

/*!
 * \brief Get TVM Op handle for Im2Col.
 */

/*!
 * \brief Clone this Im2Col operator.
 *
 * Returns a TileOperator reference that is a shallow clone of this operator.
 */
class CopyNode : public TileOperatorNode {
public:
  Buffer src, dst;                   // Source and destination buffers
  Array<Range> src_range, dst_range; // Ranges for each dimension in src and dst
  Optional<PrimExpr> dst_block;      // Destination block index for cluster copy
  Map<String, ObjectRef> annotations; // Backend/pass-specific annotations.
  // Common SIMT annotation keys:
  //   - "coalesced_width": IntImm, width for coalesced memory access.
  //   - "dst_block": PrimExpr, destination CTA rank for cluster copy.
  //   - attr::kParallelLoopLayout ("parallel_loop_layout"): Fragment, loop
  //     layout hint applied to the outermost generated parallel loop of this
  //     copy's SIMT loop nest.

  mutable ParallelOp par_op_; // Optional associated parallelization operator

  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("tl.Copy", CopyNode, TileOperatorNode);

  static void RegisterReflection() {
    namespace refl = reflection;
    refl::ObjectDef<CopyNode>()
        .def_ro("src", &CopyNode::src)
        .def_ro("dst", &CopyNode::dst)
        .def_ro("src_range", &CopyNode::src_range)
        .def_ro("dst_range", &CopyNode::dst_range)
        .def_ro("dst_block", &CopyNode::dst_block)
        .def_ro("annotations", &CopyNode::annotations);
  }

  /*!
   * \brief Lower the copy operator to a TIR statement.
   * \param lower_args Arguments for lowering.
   * \param analyzer Analyzer for simplification and bounds checks.
   */
  Stmt Lower(const LowerArgs &lower_args,
             arith::Analyzer *analyzer) const override;

  /*!
   * \brief Infer buffer layouts after applying this operator.
   * \param layout_args Arguments for layout inference.
   * \param level Level of inference (basic or detailed).
   */
  LayoutMap InferLayout(const LayoutInferArgs &layout_args,
                        InferLevel level) const override;

  /*!
   * \brief Infer layout through the generated SIMT copy loop.
   */
  LayoutMap InferSIMTLayout(const LayoutInferArgs &layout_args,
                            InferLevel level) const;

  /*!
   * \brief Generate lowering for MACA memory async copy (memcpy_async).
   */
  Stmt LowerMACAMemcpyAsync(const LowerArgs &T,
                            arith::Analyzer *analyser) const;

  /*!
   * \brief Generate SIMT (thread-level) loop for copying.
   */
  For MakeSIMTLoop(arith::Analyzer *analyzer) const;

  /*!
   * \brief Create iterator variables for multi-dimensional copy loops.
   */
  Array<IterVar> MakeIterVars() const;

  /*!
   * \brief Calculate source or destination indices from iteration vars.
   * \param ivs      Iterator variables from MakeIterVars().
   * \param src_dst  0 = make source indices, 1 = make destination indices.
   */
  Array<PrimExpr> MakeIndices(const Array<IterVar> &ivs, int src_dst) const;

  /*!
   * \brief Construct the boundary predicate for valid copy (to avoid OOB).
   * \param analyzer  Arithmetic analyser for simplification.
   * \param ivs       Iterator variables.
   * \param extents   Extent expressions for the relevant buffer.
   * \param src_dst   0 = predicate for source, 1 = predicate for destination.
   */
  PrimExpr MakePredicate(arith::Analyzer *analyzer, const Array<IterVar> &ivs,
                         Array<PrimExpr> extents, int src_dst) const;

protected:
  /**
   * \brief Create a deep copy of this operator.
   *
   * Returns a TileOperator that is a copy of the current node, preserving all
   * configuration (buffers, parameters, and layout-related fields).
   * @return A TileOperator owning the cloned operator node.
   */

  /**
   * \brief Constructor.
   * \param args Expression arguments for the Im2Col operator.
   * \param vmap Buffer variable mapping.
   */

  /**
   * \brief Get the TVM Op handle corresponding to this Im2Col operator.
   * @return Reference to the singleton TVM Op representing this operator.
   */
  TileOperator Clone() const;
};

using CopyTargetPredicate = bool (*)(Target target);

struct CopyImpl {
  const char *name;
  CopyTargetPredicate match_target;
  int priority;

  LayoutMap (*infer_layout)(const CopyNode &op,
                            const LayoutInferArgs &layout_args,
                            InferLevel level);

  Stmt (*lower)(const CopyNode &op, const LowerArgs &lower_args,
                arith::Analyzer *analyzer);
};

void RegisterCopyImpl(CopyImpl impl);

Stmt LowerNormalCopy(const CopyNode &op, const LowerArgs &lower_args,
                     arith::Analyzer *analyzer);

class Copy : public TileOperator {
public:
  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(Copy, TileOperator, CopyNode);

  /*!
   * \brief Constructor.
   * \param args  Expression arguments for the copy.
   * \param annotations  Annotations map from the Call node.
   */
  TVM_DLL Copy(Array<PrimExpr> args,
               Map<String, ObjectRef> annotations = Map<String, ObjectRef>());

  /*!
   * \brief Get the TVM Op handle corresponding to this Copy op.
   */
  static const Op &Get();
};

/*!
 * \brief Special operator for Im2Col transformation.
 *
 * This operator converts input image layout into columnar format suitable
 * for matrix multiplication-based convolution lowering.
 */
class Im2ColOpNode : public TileOperatorNode {
public:
  BufferRegion srcRegion_, dstRegion_;
  Buffer src_,
      dst_;      // Source (input feature map) and destination (im2col matrix)
  int stride_;   // Stride for convolution
  int padding_;  // Padding amount
  int dilation_; // Dilation factor
  int kernel_;   // Kernel size
  int eviction_policy_;                // Cache eviction policy
  PrimExpr nhw_step_;                  // Step size in NHW dimensions
  PrimExpr c_step_;                    // Step size in channel dimension
  Map<String, ObjectRef> annotations_; // Annotations from Call node

  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("tl.Im2Col", Im2ColOpNode,
                                    TileOperatorNode);

  static void RegisterReflection() {
    namespace refl = reflection;
    refl::ObjectDef<Im2ColOpNode>()
        .def_ro("srcRegion", &Im2ColOpNode::srcRegion_)
        .def_ro("dstRegion", &Im2ColOpNode::dstRegion_)
        .def_ro("src", &Im2ColOpNode::src_)
        .def_ro("dst", &Im2ColOpNode::dst_)
        .def_ro("stride", &Im2ColOpNode::stride_)
        .def_ro("padding", &Im2ColOpNode::padding_)
        .def_ro("dilation", &Im2ColOpNode::dilation_)
        .def_ro("kernel", &Im2ColOpNode::kernel_)
        .def_ro("eviction_policy", &Im2ColOpNode::eviction_policy_);
  }

  /*!
   * \brief Lower to TIR statement.
   */
  Stmt Lower(const LowerArgs &lower_args,
             arith::Analyzer *analyzer) const override;

  /*!
   * \brief Infer layout for this operator.
   */
  LayoutMap InferLayout(const LayoutInferArgs &layout_args,
                        InferLevel level) const override;

  /*!
   * \brief Get TVM Op handle.
   */
  static const Op &Get();
  TileOperator Clone() const;
};

struct Im2ColImpl {
  const char *name;
  CopyTargetPredicate match_target;
  int priority;

  Stmt (*lower)(const Im2ColOpNode &op, const LowerArgs &lower_args,
                arith::Analyzer *analyzer);
};

void RegisterIm2ColImpl(Im2ColImpl impl);

class Im2ColOp : public TileOperator {
public:
  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(Im2ColOp, TileOperator,
                                             Im2ColOpNode);
  TVM_DLL
  Im2ColOp(Array<PrimExpr> args,
           Map<String, ObjectRef> annotations = Map<String, ObjectRef>());
  static const Op &Get();
};

} // namespace tl
} // namespace tvm

#endif // TVM_TL_OP_COPY_H_

