37	             arith::Analyzer *analyzer) const override;
38	  LayoutMap InferLayout(const LayoutInferArgs &layout_args,
39	                        InferLevel level) const override;
40	  TileOperator Clone() const override;
41	
42	  /// Build a SIMT-style nested parallel loop implementing the transpose.
43	  For MakeSIMTLoop(arith::Analyzer *analyzer) const;
44	
45	private:
46	  /// Create iterator variables for dimensions with extent > 1.
47	  Array<IterVar> MakeIterVars() const;
48	
49	  /// Generate source (src_dst=0) or destination (src_dst=1) index expressions.
